-- SIN's change (1amcoff1n), Respawn All OpenWorld for 0.1.35, part 01-three-zones/apply.sql. Off unless Respawn.DynamicMode = 1
-- (worldserver.conf, default 0): this file only puts the spawns in spawn group 901035 (dynamic rate flag).
-- Forever Bots 0.1.35, run in the world database, MySQL 8.
CREATE TEMPORARY TABLE respawn45_candidates (guid BIGINT UNSIGNED PRIMARY KEY, map_id INT UNSIGNED, entry INT UNSIGNED);
START TRANSACTION;
SELECT 901035,'Forever 0.1.35 - dynamic open-world combat - three zones',9 WHERE NOT EXISTS (SELECT 1 FROM spawn_group_template WHERE groupId=901035);
SELECT t.groupId,0,c.guid FROM respawn45_candidates a
JOIN creature c ON c.guid=a.guid AND c.id=a.entry AND c.map=a.map_id
JOIN spawn_group_template t ON t.groupId=901035 AND t.groupName='Forever 0.1.35 - dynamic open-world combat - three zones' AND t.groupFlags=9
WHERE NOT EXISTS (SELECT 1 FROM spawn_group s WHERE s.spawnType=0 AND s.spawnId=c.guid);
COMMIT;
SELECT COUNT(*) AS active_members FROM spawn_group s JOIN spawn_group_template t USING(groupId)
WHERE t.groupId=901035 AND t.groupName='Forever 0.1.35 - dynamic open-world combat - three zones' AND t.groupFlags=9;
DROP TEMPORARY TABLE respawn45_candidates;
